 for(int i=0;i<8;i++){var g=(GameObject)PrefabUtility.InstantiatePrefab(source);PrefabUtility.UnpackPrefabInstance(g,PrefabUnpackMode.Completely,InteractionMode.AutomatedAction);g.name="Derby full NWH tractor "+(i+1);float angle=i*Mathf.PI/4;g.transform.SetPositionAndRotation(new Vector3(Mathf.Sin(angle)*29,1.3f,Mathf.Cos(angle)*29),Quaternion.Euler(0,i*45+180,0));var vc=g.GetComponent<VehicleController>();foreach(var mb in g.GetComponentsInChildren<MonoBehaviour>(true)){if(mb==vc||mb is DamageHandler||mb is NWH.WheelController3D.WheelController)continue;string name=mb.GetType().Name;if(name.EndsWith("ModuleWrapper")&&!name.StartsWith("ABS")&&!name.StartsWith("Aerodynamics")||name=="FollowVehicleState"||name=="CameraChanger"||name.StartsWith("CameraMouse")||name=="CameraInsideVehicle"||name.StartsWith("Cinemachine")||name=="PostProcessLayer")UnityEngine.Object.DestroyImmediate(mb);}var allCameras=g.GetComponentsInChildren<Camera>(true);var driver=allCameras.First(c=>c.name=="Vehicle Camera Driver");var seat=new GameObject("Stable original NWH driver seat").transform;seat.SetParent(g.transform,false);seat.position=driver.transform.position;seat.rotation=g.transform.rotation;var mirrors=allCameras.Where(c=>c.name.StartsWith("RenderTextureMirrorCamera")).OrderBy(c=>c.name).ToArray();foreach(var c in allCameras)if(!mirrors.Contains(c))UnityEngine.Object.DestroyImmediate(c.gameObject);foreach(var c in g.GetComponentsInChildren<AudioListener>(true))UnityEngine.Object.DestroyImmediate(c);foreach(var canvas in g.GetComponentsInChildren<Canvas>(true))UnityEngine.Object.DestroyImmediate(canvas.gameObject);foreach(var collider in g.GetComponentsInChildren<Collider>(true))collider.gameObject.layer=0;
