 static DerbyPoseBridge Proxy(DerbyFighter f){var bridge=f.gameObject.AddComponent<DerbyPoseBridge>();bridge.fighter=f;bridge.actual=f.GetComponentsInChildren<MeshFilter>(true);bridge.renderers=bridge.actual.Select(a=>a.GetComponent<Renderer>()).ToArray();bridge.copies=new MeshFilter[bridge.actual.Length];bridge.proxy=new GameObject("Stable actual-mesh replay source "+f.slot).transform;bridge.proxy.SetPositionAndRotation(f.body.position,f.body.rotation);for(int i=0;i<bridge.actual.Length;i++){var a=bridge.actual[i];var g=new GameObject(a.name);g.transform.SetParent(bridge.proxy,false);g.transform.SetPositionAndRotation(a.transform.position,a.transform.rotation);g.transform.localScale=a.transform.lossyScale;bridge.copies[i]=g.AddComponent<MeshFilter>();bridge.copies[i].sharedMesh=a.sharedMesh;var r=g.AddComponent<MeshRenderer>();r.sharedMaterials=bridge.renderers[i].sharedMaterials;r.enabled=false;}f.assembly=bridge.proxy;return bridge;}
 static ParticleSystem Fx(string name,Transform parent,Color color,bool loop,int count,float speed,float size){var smokePrefab=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/NWH/Vehicle Physics 2/Effects/Prefabs/ExhaustSmoke.prefab");if(smokePrefab==null)throw new Exception("Installed NWH smoke emitter required");var model=UnityEngine.Object.Instantiate(smokePrefab);model.name=name;var p=model.GetComponent<ParticleSystem>();p.transform.SetParent(parent,false);p.Stop(true,ParticleSystemStopBehavior.StopEmittingAndClear);var main=p.main;main.loop=loop;main.playOnAwake=false;main.startLifetime=loop?1.4f:.65f;main.startSpeed=speed;main.startSize=size;main.startColor=color;main.maxParticles=loop?96:48;main.simulationSpace=ParticleSystemSimulationSpace.World;main.gravityModifier=loop?-.1f:.7f;var emission=p.emission;emission.rateOverTime=loop?count:0;if(!loop)emission.SetBursts(new[]{new ParticleSystem.Burst(0,(short)count)});var shape=p.shape;shape.shapeType=ParticleSystemShapeType.Cone;shape.radius=.35f;shape.angle=30;var material=SportsChaosAuthoring.Flare(Folder);if(name.Contains("smoke")||name.Contains("droplets")){string path="Assets/"+Folder+"/Materials/Soft alpha smoke.mat";material=AssetDatabase.LoadAssetAtPath<Material>(path);if(material==null){material=new Material(Shader.Find("Universal Render Pipeline/Particles/Unlit"));material.SetFloat("_Surface",1);material.SetFloat("_Blend",0);material.SetFloat("_SrcBlend",5);material.SetFloat("_DstBlend",10);material.SetFloat("_ZWrite",0);material.renderQueue=3000;material.EnableKeyword("_SURFACE_TYPE_TRANSPARENT");material.mainTexture=SportsChaosAuthoring.Flare(Folder).mainTexture;AssetDatabase.CreateAsset(material,path);}}p.GetComponent<ParticleSystemRenderer>().sharedMaterial=material;return p;}
 static void Stadium(DerbyMatch m,Material navy,Material ivory){var destination=SceneManager.GetActiveScene();var source=EditorSceneManager.OpenScene("Assets/TruckFieldGoal/Scenes/TruckFieldGoal.unity",OpenSceneMode.Additive);try{SceneManager.SetActiveScene(destination);var old=source.GetRootGameObjects().First(g=>g.name=="Reused Union Field stadium render geometry");var copy=UnityEngine.Object.Instantiate(old);copy.name="Existing Union Field grandstands and press boxes";SceneManager.MoveGameObjectToScene(copy,destination);copy.transform.position-=Vector3.forward*30;}finally{EditorSceneManager.CloseScene(source,true);SceneManager.SetActiveScene(destination);}Crowd();for(int side=-1;side<=1;side+=2){var screen=SportsEventAuthoring.Box("Giant Derby broadcast screen "+side,new Vector3(side*39,12,28),new Vector3(17,9,.8f),navy);var label=new GameObject("Event screen readable rules").AddComponent<TextMeshPro>();label.transform.SetParent(screen.transform,false);label.transform.localPosition=new Vector3(0,0,-.52f);label.transform.localScale=new Vector3(.055f,.11f,1);label.rectTransform.sizeDelta=new Vector2(290,74);label.text="TRUCK DERBY\nKEEP MOVING\n5s STOP = FIRE";label.font=SportsBroadcastAuthoring.Theme().headingFont;label.fontSize=28;label.alignment=TextAlignmentOptions.Center;label.color=new Color(1,.89f,.65f);for(int n=0;n<4;n++){var light=new GameObject("Budgeted stadium floodlight").AddComponent<Light>();light.type=LightType.Spot;light.transform.position=new Vector3(side*36,17,-30+n*20);light.transform.LookAt(new Vector3(0,0,-20+n*14));light.range=65;light.spotAngle=80;light.intensity=1800;light.shadows=LightShadows.None;}}}
 static void Crowd(){var paths=AssetDatabase.FindAssets("Taxi_Girl_11 t:Prefab").Select(AssetDatabase.GUIDToAssetPath).ToArray();if(paths.Length==0)return;var source=AssetDatabase.LoadAssetAtPath<GameObject>(paths[0]);var model=UnityEngine.Object.Instantiate(source);var skins=model.GetComponentsInChildren<SkinnedMeshRenderer>(true);var root=new GameObject("Installed character crowd — baked low-cost spectators").transform;for(int k=0;k<skins.Length;k++){var skin=skins[k];var mesh=new Mesh();skin.BakeMesh(mesh);string path="Assets/"+Folder+"/Models/Crowd baked "+k+".asset";var saved=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(saved==null){AssetDatabase.CreateAsset(mesh,path);saved=mesh;}else{EditorUtility.CopySerialized(mesh,saved);UnityEngine.Object.DestroyImmediate(mesh);}for(int n=0;n<64;n++){float a=n*Mathf.PI*2/64;var g=new GameObject("Spectator "+n+" mesh "+k);g.transform.SetParent(root,false);g.transform.SetPositionAndRotation(new Vector3(Mathf.Sin(a)*52,2+(n%3)*.4f,Mathf.Cos(a)*52),Quaternion.Euler(0,n*360f/64+180,0));g.AddComponent<MeshFilter>().sharedMesh=saved;g.AddComponent<MeshRenderer>().sharedMaterials=skin.sharedMaterials;}}UnityEngine.Object.DestroyImmediate(model);}
 static StateSettings Settings(StateSettings original){string path="Assets/"+Folder+"/Materials/Derby full physical NWH state.asset";var state=AssetDatabase.LoadAssetAtPath<StateSettings>(path);if(state==null){state=UnityEngine.Object.Instantiate(original);state.name="Derby all participant full physical state";AssetDatabase.CreateAsset(state,path);}state.definitions=original.definitions.Select(d=>new StateDefinition(d.fullName,d.isEnabled,-1)).ToList();string lodPath="Assets/"+Folder+"/Materials/Derby stadium full detail LOD.asset";var lod=AssetDatabase.LoadAssetAtPath<NWH.VehiclePhysics2.LOD>(lodPath);if(lod==null){lod=ScriptableObject.CreateInstance<NWH.VehiclePhysics2.LOD>();AssetDatabase.CreateAsset(lod,lodPath);}lod.distance=10000;state.LODs=new List<NWH.VehiclePhysics2.LOD>{lod};EditorUtility.SetDirty(lod);EditorUtility.SetDirty(state);return state;}
 static void Props(DerbyMatch match){var root=new GameObject("Physical reusable event obstacles").transform;var owner=match.gameObject.AddComponent<DerbyProps>();match.props=owner;var sources=new List<Transform>();var bodies=new List<Rigidbody>();var breaks=new List<DerbyBreakableProp>();for(int i=0;i<16;i++){float a=i*Mathf.PI*2/16;var holder=new GameObject("Installed physical moveable barrel "+i).transform;holder.SetParent(root,false);holder.position=new Vector3(Mathf.Sin(a)*20,0,Mathf.Cos(a)*20);LWS.TruckKeepaway.Editor.KeepawayPresentationAuthoring.Fit(holder,"Assets/ConstructionPropsBundle/URP/Prefabs/SM_Barrel01 Variant.prefab",new Vector3(1.2f,1.5f,1.2f),0,true,Folder);foreach(var c in holder.GetComponentsInChildren<Collider>())UnityEngine.Object.DestroyImmediate(c);var shape=holder.gameObject.AddComponent<BoxCollider>();shape.center=Vector3.up*.75f;shape.size=new Vector3(1.2f,1.5f,1.2f);var body=holder.gameObject.AddComponent<Rigidbody>();body.mass=70;body.linearDamping=.18f;body.angularDamping=.4f;body.maxLinearVelocity=20;sources.Add(holder);bodies.Add(body);}for(int i=0;i<4;i++){var prop=new GameObject("Core-Collapse pooled concrete barrier "+i);prop.transform.SetParent(root,false);prop.transform.position=new Vector3(i%2==0?-24:24,.55f,i<2?-10:10);var intact=new GameObject("Installed concrete road barrier model").transform;intact.SetParent(prop.transform,false);LWS.TruckKeepaway.Editor.KeepawayPresentationAuthoring.Fit(intact,"Assets/RoadPropsPack/URP/Prefabs/RoadBlock01_URP.prefab",new Vector3(4.5f,1,.9f),0,false,Folder);var solid=prop.AddComponent<BoxCollider>();solid.size=new Vector3(4.5f,1,.9f);var core=prop.AddComponent<DerbyBreakableProp>();core.match=match;core.intact=intact.gameObject;core.solids=new Collider[]{solid};var support=prop.GetComponent<Assets.CoreCollapse.Scripts.Structural.Support>();support.ClearSupports();var eventField=typeof(Assets.CoreCollapse.Scripts.Structural.Support).GetField("onCollapse",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic);if(eventField.GetValue(support)==null)eventField.SetValue(support,new Assets.CoreCollapse.Scripts.Structural.Support.OnCollapseEvent());var settings=new SerializedObject(core);settings.FindProperty("startingHp").floatValue=90;settings.ApplyModifiedPropertiesWithoutUndo();var fragmentSource=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/TruckBungeeDemolition/Prefabs/Prefractured structural column.prefab");if(fragmentSource==null)throw new Exception("Existing Core-Collapse prefractured cluster model required");var fragments=UnityEngine.Object.Instantiate(fragmentSource,prop.transform,false);fragments.name="Pooled existing irregular Core-Collapse fracture clusters";foreach(var mb in fragments.GetComponentsInChildren<MonoBehaviour>(true))UnityEngine.Object.DestroyImmediate(mb);fragments.transform.localRotation=Quaternion.Euler(0,0,90);core.fragments=fragments.GetComponentsInChildren<Rigidbody>();core.rest=core.fragments.Select(b=>b.transform.localPosition).ToArray();core.rotation=core.fragments.Select(b=>b.transform.localRotation).ToArray();foreach(var b in core.fragments){b.mass=350;b.maxLinearVelocity=20;b.maxAngularVelocity=9;b.collisionDetectionMode=CollisionDetectionMode.ContinuousDynamic;b.interpolation=RigidbodyInterpolation.Interpolate;b.isKinematic=true;b.detectCollisions=false;b.transform.localScale=Vector3.zero;}sources.Add(prop.transform);breaks.Add(core);}owner.sources=sources.ToArray();owner.movable=bodies.ToArray();owner.positions=bodies.Select(b=>b.position).ToArray();owner.rotations=bodies.Select(b=>b.rotation).ToArray();owner.breakable=breaks.ToArray();}
 public static void Validate(){var m=UnityEngine.Object.FindAnyObjectByType<DerbyMatch>();if(m==null){EditorSceneManager.OpenScene(Scene);m=UnityEngine.Object.FindAnyObjectByType<DerbyMatch>();}if(m==null||m.fighters.Length!=8||m.replay.sources.Length!=28||m.dents.slots.Length!=8||m.cabCameras.Length!=4)throw new Exception("Derby complete scene references required");foreach(var f in m.fighters)if(f.vehicle==null||f.deform==null||!f.deform.visualOnly||f.deform.decelerationThreshold<1e8f||f.mirrors.mirrors.Length!=2||f.mirrors.glass.Length!=2||f.mirrors.glass[0].name!="mirror lft.001"||f.mirrors.glass[1].name!="mirror rt.001"||f.fragments.pieces.Length!=12)throw new Exception("NWH sole deformation/powertrain and existing mirror/fragment foundation required");if(UnityEngine.Object.FindObjectsByType<AudioListener>(FindObjectsInactive.Include).Length!=1)throw new Exception("One Derby listener required");Debug.Log("DERBY_NATIVE_SCENE_VALIDATED");}
